# This code has been fully generated by an AI.
"""Tests for the garmin-fetch protocol, using a fake Garmin client."""

from __future__ import annotations

import io
import json
import tempfile
import unittest
import zipfile
from enum import Enum, auto
from pathlib import Path
from typing import Any

from garmin_fetch.cli import Exit, extract_fit, main

FIT = b"\x0e\x10\x00\x00\x00\x00\x00\x00.FIT" + b"\x00" * 20


def zipped(name: str, data: bytes) -> bytes:
    buf = io.BytesIO()
    with zipfile.ZipFile(buf, "w") as zf:
        zf.writestr(name, data)
    return buf.getvalue()


# Same class names as garminconnect, so the name-based classification applies.
class GarminConnectAuthenticationError(Exception):
    pass


class GarminConnectTooManyRequestsError(Exception):
    pass


class GarminConnectNotFoundError(Exception):
    pass


class FakeGarmin:
    class ActivityDownloadFormat(Enum):
        ORIGINAL = auto()
        TCX = auto()

    activities: list[dict[str, Any]] = []
    files: dict[str, bytes] = {}
    valid_tokens = True
    login_error: Exception | None = None
    requires_mfa = False
    instances: list["FakeGarmin"] = []

    def __init__(self, email=None, password=None, prompt_mfa=None, **_: Any) -> None:
        self.email, self.password, self.prompt_mfa = email, password, prompt_mfa
        self.downloads: list[str] = []
        FakeGarmin.instances.append(self)

    def login(self, tokenstore: str | None = None):
        if self.login_error:
            raise self.login_error
        if self.email:
            if self.requires_mfa and self.prompt_mfa() != "123456":
                raise GarminConnectAuthenticationError("MFA code rejected")
            Path(tokenstore, "garmin_tokens.json").write_text("{}")
            return None, None
        if not self.valid_tokens:
            raise GarminConnectAuthenticationError("Username and password are required")
        return None, None

    def get_activities_by_date(self, startdate, enddate=None, activitytype=None, sortorder=None):
        return self.activities

    def download_activity(self, activity_id, dl_fmt=ActivityDownloadFormat.TCX):
        assert dl_fmt is FakeGarmin.ActivityDownloadFormat.ORIGINAL
        self.downloads.append(activity_id)
        if activity_id not in self.files:
            raise GarminConnectNotFoundError(f"404 for {activity_id}")
        return self.files[activity_id]


def activity(activity_id: int, name: str = "Morning Ride") -> dict[str, Any]:
    return {
        "activityId": activity_id,
        "activityName": name,
        "activityType": {"typeKey": "road_biking"},
        "startTimeGMT": "2026-05-01 06:00:00",
        "distance": 42000.0,
        "duration": 5400.0,
        "deviceId": 3412345678,
    }


class CliTestCase(unittest.TestCase):
    def setUp(self) -> None:
        self.tmp = Path(tempfile.mkdtemp())
        FakeGarmin.activities = []
        FakeGarmin.files = {}
        FakeGarmin.valid_tokens = True
        FakeGarmin.login_error = None
        FakeGarmin.requires_mfa = False
        FakeGarmin.instances = []

    def run_cli(self, *argv: str, stdin: str = "") -> tuple[int, list[dict[str, Any]]]:
        out = io.StringIO()
        code = main(list(argv), stdin=io.StringIO(stdin), stdout=out, factory=FakeGarmin)
        events = [json.loads(line) for line in out.getvalue().splitlines()]
        return code, events

    def sync(self, *extra: str) -> tuple[int, list[dict[str, Any]]]:
        return self.run_cli(
            "sync", "--tokenstore", str(self.tmp / "tokens"), "--out", str(self.tmp / "inbox"),
            "--since", "2026-01-01", "--delay", "0", *extra,
        )


class LoginTest(CliTestCase):
    def test_login_without_mfa_stores_tokens(self) -> None:
        code, events = self.run_cli("login", "--tokenstore", str(self.tmp / "t"),
                                    stdin='{"email": "a@b.c", "password": "pw"}\n')
        self.assertEqual(code, Exit.OK)
        self.assertEqual(events, [{"event": "login_ok"}])
        self.assertTrue((self.tmp / "t" / "garmin_tokens.json").exists())

    def test_login_with_mfa_reads_code_from_stdin(self) -> None:
        FakeGarmin.requires_mfa = True
        code, events = self.run_cli("login", "--tokenstore", str(self.tmp / "t"),
                                    stdin='{"email": "a@b.c", "password": "pw"}\n{"mfa_code": "123456"}\n')
        self.assertEqual(code, Exit.OK)
        self.assertEqual([e["event"] for e in events], ["mfa_required", "login_ok"])

    def test_login_with_missing_mfa_code_fails(self) -> None:
        FakeGarmin.requires_mfa = True
        code, events = self.run_cli("login", "--tokenstore", str(self.tmp / "t"),
                                    stdin='{"email": "a@b.c", "password": "pw"}\n')
        self.assertEqual(code, Exit.ERROR)
        self.assertEqual(events[-1]["code"], "bad_input")

    def test_secrets_are_never_echoed(self) -> None:
        FakeGarmin.login_error = GarminConnectAuthenticationError("Authentication failed (401)")
        code, events = self.run_cli("login", "--tokenstore", str(self.tmp / "t"),
                                    stdin='{"email": "a@b.c", "password": "s3cr3t"}\n')
        self.assertEqual(code, Exit.AUTH_REQUIRED)
        self.assertNotIn("s3cr3t", json.dumps(events))

    def test_login_requires_credentials(self) -> None:
        code, events = self.run_cli("login", "--tokenstore", str(self.tmp / "t"), stdin="{}\n")
        self.assertEqual(code, Exit.ERROR)
        self.assertEqual(events[-1]["code"], "bad_input")


class StatusTest(CliTestCase):
    def test_expired_tokens_require_login(self) -> None:
        FakeGarmin.valid_tokens = False
        code, events = self.run_cli("status", "--tokenstore", str(self.tmp / "t"))
        self.assertEqual(code, Exit.AUTH_REQUIRED)
        self.assertEqual(events[-1], {"event": "error", "code": "auth_required",
                                      "message": "Username and password are required"})

    def test_rate_limit_is_reported(self) -> None:
        FakeGarmin.login_error = GarminConnectTooManyRequestsError("429")
        code, events = self.run_cli("status", "--tokenstore", str(self.tmp / "t"))
        self.assertEqual(code, Exit.RATE_LIMITED)
        self.assertEqual(events[-1]["code"], "rate_limited")


class SyncTest(CliTestCase):
    def test_downloads_new_activities_as_fit(self) -> None:
        FakeGarmin.activities = [activity(101), activity(102)]
        FakeGarmin.files = {"101": zipped("101_ACTIVITY.fit", FIT), "102": FIT}
        code, events = self.sync()

        self.assertEqual(code, Exit.OK)
        self.assertEqual([e.get("status") for e in events[:-1]], ["downloaded", "downloaded"])
        self.assertEqual(events[-1], {"event": "done", "listed": 2, "downloaded": 2, "skipped": 0, "no_file": 0})
        self.assertEqual((self.tmp / "inbox" / "101.fit").read_bytes(), FIT)
        meta = json.loads((self.tmp / "inbox" / "101.json").read_text())
        self.assertEqual(meta["type"], "road_biking")
        self.assertFalse(list((self.tmp / "inbox").glob("*.part")))

    def test_second_run_is_idempotent(self) -> None:
        FakeGarmin.activities = [activity(101)]
        FakeGarmin.files = {"101": FIT}
        self.sync()
        code, events = self.sync()
        self.assertEqual(code, Exit.OK)
        self.assertEqual(events[0]["status"], "known")
        self.assertEqual(FakeGarmin.instances[-1].downloads, [])

    def test_known_ids_skip_download_but_report_metadata(self) -> None:
        FakeGarmin.activities = [activity(101, "Renamed ride")]
        known = self.tmp / "known.txt"
        known.write_text("101\n")
        code, events = self.sync("--known-ids", str(known))
        self.assertEqual(code, Exit.OK)
        self.assertEqual(events[0]["status"], "known")
        self.assertEqual(events[0]["name"], "Renamed ride")

    def test_activities_without_fit_are_reported(self) -> None:
        FakeGarmin.activities = [activity(201), activity(202)]
        FakeGarmin.files = {"202": zipped("202.gpx", b"<gpx/>")}  # 201 → 404
        code, events = self.sync()
        self.assertEqual(code, Exit.OK)
        self.assertEqual([e["status"] for e in events[:-1]], ["no_file", "no_file"])
        self.assertEqual(events[-1]["no_file"], 2)

    def test_expired_tokens_abort_sync(self) -> None:
        FakeGarmin.valid_tokens = False
        code, _ = self.sync()
        self.assertEqual(code, Exit.AUTH_REQUIRED)

    def test_invalid_since_is_rejected(self) -> None:
        with self.assertRaises(SystemExit):
            self.run_cli("sync", "--tokenstore", "t", "--out", "o", "--since", "01.05.2026")


class ExtractFitTest(unittest.TestCase):
    def test_variants(self) -> None:
        self.assertEqual(extract_fit(FIT), FIT)
        self.assertEqual(extract_fit(zipped("x.fit", FIT)), FIT)
        self.assertIsNone(extract_fit(zipped("x.fit", b"not a fit file at all")))
        self.assertIsNone(extract_fit(b"<gpx/>"))


if __name__ == "__main__":
    unittest.main()
